#include <bits/stdc++.h>
#define lld long long int
#define vec vector<lld>
#define pll pair<lld, lld>
#define pb push_back
#define ss second
#define ff first
#define mp make_pair
#define answer cout << endl << "answer : ";
#define messi ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);
#define rep(i, n) for (int i = 0; i < (n); i++)
#define all(x) (x).begin(), (x).end()
#define rall(x) (x).rbegin(), (x).rend()

using namespace std;

const int N = 200002;
const int MOD = 998244353;

lld a[N], f[N], rf[N], pk[N];

lld pw(lld x, lld k) {
    lld res = 1;
    for (int i = 30; i >= 0; i--) {
        res = res * res % MOD;
        if (k & (1LL << i))
            res = res * x % MOD;
    }
    return res;
}

lld rev(lld x) {
    return pw(x, MOD - 2);
}

int main() {
    messi

    lld n, k, r = 0;
    cin >> n >> k;

    if (k == 1) {
        cout << 0;
        return 0;
    }

    f[0] = rf[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = f[i - 1] * i % MOD;
        rf[i] = rev(f[i]);
    }

    rep(i, n)
        cin >> a[i];

    rep(i, n)
        if (a[i] != a[(i + 1) % n])
            r++;

    lld ans = 0;
    for (int i = 0; 2 * i <= r; i++) {
        ans = (ans + f[r] * rf[i] % MOD * rf[i] % MOD *
                     rf[r - 2 * i] % MOD * pw(k - 2, r - 2 * i) % MOD) % MOD;
    }

    cout << ((pw(k, r) + MOD - ans) % MOD * rf[2] % MOD) *
                pw(k, n - r) % MOD
         << '\n';

    return 0;
}

